const body = $json.body ?? $json;
const symbol = body?.symbol;
const timeframe = body?.timeframe;
const mode = body?.mode;
const marketContext = body?.market_context;
const paperContext = body?.paper_context;
const pairOk = typeof symbol === 'string' && /^[A-Z0-9]+\/[A-Z0-9]+$/.test(symbol);
const timeframeOk = typeof timeframe === 'string' && /^\d+[mhdw]$/.test(timeframe);
const contextOk = marketContext && marketContext.symbol === symbol && marketContext.timeframe === timeframe &&
  marketContext.current && Number.isFinite(Number(marketContext.current.price)) && Array.isArray(marketContext.candles) &&
  marketContext.historicalSummary && Array.isArray(marketContext.historicalSummary.dailySeries);
if (!pairOk || !timeframeOk || mode !== 'DRY_RUN' || !contextOk) {
  return [{ json: { ok: false, statusCode: 400, error: { code: 'INVALID_INPUT', message: 'symbol, timeframe, DRY_RUN mode, and backend market_context are required.' } } }];
}
return [{ json: { ok: true, symbol, timeframe, mode: 'DRY_RUN', marketContext, paperContext: paperContext ?? null } }];

try {
  const request = $('Validate Input').first().json;
  const context = request.marketContext;
  if (!context?.current || !Array.isArray(context.candles) || context.candles.length === 0 || !context.historicalSummary) {
    return [{ json: { ok: false, statusCode: 502, error: { code: 'NO_MARKET_CONTEXT', message: 'The backend did not provide stored market history.' } } }];
  }
  return [{ json: { ok: true, context } }];
} catch (error) {
  return [{ json: { ok: false, statusCode: 502, error: { code: 'MARKET_CONTEXT_INVALID', message: 'Could not read the backend market context.' } } }];
}

