      reason: { type: 'string' }
    }, required: ['decision', 'confidence', 'entry', 'stop_loss', 'take_profit', 'reason']
  } } },
  messages: [
    { role: 'system', content: 'Você é um componente experimental de análise de mercado. Retorne somente o objeto JSON do schema. Avalie os dados recebidos sem inventar nem recalcular indicadores. Escreva o campo reason em Português do Brasil. HOLD é uma decisão válida; nunca force BUY ou SELL. Se os dados não sustentarem uma conclusão clara, retorne HOLD. Este é um registro de pesquisa em simulação, não uma recomendação de investimento. Use null para entry, stop_loss e take_profit quando não houver justificativa. Confidence deve ser um número entre 0 e 1.' },
    { role: 'user', content: 'Analise este contexto de mercado do Freqtrade em Português do Brasil. Use o portfólio simulado e as estatísticas anteriores como contexto, sem afirmar desempenho comprovado quando a amostra for pequena.\nCONTEXTO DE MERCADO:\n' + JSON.stringify($('Prepare AI Context').first().json.context) + '\nCONTEXTO DO PAPER TRADING:\n' + JSON.stringify($('Prepare AI Context').first().json.paperContext) }
  ]
}) }}

